<?php $pageTitle='Tournaments';require_once __DIR__.'/../includes/header.php';require_once __DIR__.'/../includes/sidebar.php';requireRole(['owner','manager']);$db=getDB();$club=$_SESSION['club_id'];if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$name=sanitize($_POST['name']??'');if($name){$db->prepare("INSERT INTO tournaments(club_id,name,sport,format,match_format,frames_count,entry_fee,prize_pool,status,created_by) VALUES(?,?,?,?,?,?,?,?, 'registration',?)")->execute([$club,$name,$_POST['sport']??'snooker',$_POST['format']??'single_elim',$_POST['match_format']??'best_of',max(1,(int)$_POST['frames_count']),max(0,(float)$_POST['entry_fee']),max(0,(float)$_POST['prize_pool']),$_SESSION['user_id']]);$flash='Tournament created and open for registration.';}}$q=$db->prepare('SELECT t.*,u.name creator FROM tournaments t JOIN users u ON u.id=t.created_by WHERE t.club_id=? ORDER BY t.created_at DESC');$q->execute([$club]);$rows=$q->fetchAll();?><div class="flex justify-between"><div><h1 class="text-2xl font-bold">Tournaments</h1><p class="text-slate-400 text-sm mt-1">Create fixtures and run club competitions.</p></div><button class="btn-primary" onclick="document.getElementById('create').classList.toggle('hidden')">Create Tournament</button></div><?php if(isset($flash)):?><p class="text-green-300 mt-4"><?=$flash?></p><?php endif?><form method="post" id="create" class="card mt-5 hidden"><input type="hidden" name="csrf_token" value="<?=csrfToken()?>"><div class="grid md:grid-cols-4 gap-3"><input class="input" name="name" required placeholder="Tournament name"><select class="input" name="sport"><option value="snooker">Snooker</option><option value="8ball">8-Ball Pool</option><option value="9ball">9-Ball Pool</option></select><select class="input" name="format"><option value="single_elim">Single Elimination</option><option value="double_elim">Double Elimination</option><option value="round_robin">Round Robin</option></select><input class="input" name="frames_count" type="number" min="1" value="3" placeholder="Frames"></div><div class="grid md:grid-cols-3 gap-3 mt-3"><select class="input" name="match_format"><option value="best_of">Best of</option><option value="race_to">Race to</option></select><input class="input" name="entry_fee" type="number" min="0" placeholder="Entry fee"><input class="input" name="prize_pool" type="number" min="0" placeholder="Prize pool"></div><button class="btn-primary mt-4">Create</button></form><section class="grid md:grid-cols-2 xl:grid-cols-3 gap-4 mt-5"><?php foreach($rows as $t):?><article class="card"><div class="flex justify-between"><h2 class="font-bold"><?=sanitize($t['name'])?></h2><span class="text-xs px-2 py-1 rounded bg-slate-700"><?=sanitize($t['status'])?></span></div><p class="text-slate-400 text-sm mt-2"><?=sanitize($t['sport'])?> · <?=str_replace('_',' ',$t['format'])?></p><p class="mt-5 text-green-400">Prize pool: <?=money($t['prize_pool'])?></p></article><?php endforeach?></section><?php require __DIR__.'/../includes/footer.php'; ?>
